import { asTyped, firstOf, makeTyped, wraps } from "../../src/typed.ts";

export function makeLoose(first, second, third) {
  return { third, first, second };
}
function same(p) {
  return p;
}
function wrapsUntyped(inner) {
  return { innerOfUntyped: inner, countOfUntyped: 1 };
}
function makeUntyped(v) {
  return { p: v, q: v };
}

export function nothingBetween(o) {
  const a = o.first;
  const b = o.second;
  const c = o.third;
  return [a, b, c];
}
export function untypedCallBetween(o, p) {
  const a = o.first;
  const x = same(p);
  const b = o.second;
  const c = o.third;
  return [a, b, c, x === p];
}
export function checkBetween(o, p) {
  const a = o.first;
  const x = asTyped(p);
  const b = o.second;
  const c = o.third;
  return [a, b, c, x === p];
}
export function tagBetween(o, p) {
  const a = o.first;
  const x = firstOf(p);
  const b = o.second;
  const c = o.third;
  return [a, b, c, x];
}
export function narrowBetween(o, p) {
  const a = o.first;
  const inner = wraps(p).inner;
  const b = o.second;
  const c = o.third;
  return [a, b, c, inner === p];
}
export function untypedWrapBetween(o, p) {
  const a = o.first;
  const inner = wrapsUntyped(p).innerOfUntyped;
  const b = o.second;
  const c = o.third;
  return [a, b, c, inner === p];
}
export function literalBetween(o, v) {
  const a = o.first;
  const t = makeTyped(v, v, v);
  const b = o.second;
  const c = o.third;
  return [a, b, c, t];
}
export function untypedLiteralBetween(o, v) {
  const a = o.first;
  const t = makeUntyped(v);
  const b = o.second;
  const c = o.third;
  return [a, b, c, t];
}

export function readsAll(o) {
  const a = o.first;
  const b = o.second;
  const c = o.third;
  return [a, b, c];
}
export function writesAll(o, first, second, third) {
  o.first = first;
  o.second = second;
  o.third = third;
}
export function readsOn(o, between) {
  const a = o.first;
  const x = between(o);
  const b = o.second;
  const c = o.third;
  return [a, x, b, c];
}
export function writesOn(o, between, v) {
  o.first = v;
  between(o);
  o.second = v + 1;
  o.third = v + 2;
}
